questionvariables.text:
/* Master arrays crafted to ensure the expected value in Part B is always an integer */
num_D_list : [10, 20, 30];
num_D : rand(num_D_list);

num_TP_list : [90, 92, 94, 95, 96, 98];
num_TP : rand(num_TP_list);

num_TN_list : [85, 90, 95];
num_TN : rand(num_TN_list);

pop_size : rand([1000, 2000, 5000]);

/* Exact fractional probabilities */
P_M : num_D / 100;
P_NM : (100 - num_D) / 100;

P_Pos_given_M : num_TP / 100;
P_Neg_given_NM : num_TN / 100;
P_Pos_given_NM : (100 - num_TN) / 100;

/* Targets */
path1 : P_M * P_Pos_given_M;
path2 : P_NM * P_Pos_given_NM;

ta1 : path1 + path2;
ta2 : pop_size * path2;

/* Display variables for clean worked solution output */
str_P_M : float(P_M);
str_P_NM : float(P_NM);
str_P_Pos_given_M : float(P_Pos_given_M);
str_P_Neg_given_NM : float(P_Neg_given_NM);
str_P_Pos_given_NM : float(P_Pos_given_NM);
str_path1 : float(path1);
str_path2 : float(path2);
str_ta1 : float(ta1);

/* Distractors */
ta1_wrong_one_path : path1; /* Only calculated True Positives */
ta2_wrong_rate : pop_size * P_Pos_given_NM; /* Multiplied population directly by conditional rate, ignoring P(NM) */
